#!/bin/sh
# Writes the Homebrew formula for a release from its checksums:
#   scripts/formula.sh 0.9.0 checksums.txt > Formula/ttyl.rb
set -eu
version=$1
sums=$2
base="https://github.com/mitanshpatelll/ttyl/releases/download/v${version}"

archive() { # url and sha256 lines for one system
	file="ttyl_${version}_$1.tar.gz"
	sum=$(awk -v f="$file" '$2 == f || $2 == "*" f { print $1 }' "$sums")
	[ -n "$sum" ] || { echo "no checksum for $file" >&2; exit 1; }
	printf '      url "%s/%s"\n      sha256 "%s"\n' "$base" "$file" "$sum"
}

cat <<RUBY
# Generated by scripts/formula.sh for each release. Don't edit by hand.
class Ttyl < Formula
  desc "Keyboard-only terminal client for WhatsApp, Telegram and Instagram DMs, minus the feeds"
  homepage "https://github.com/mitanshpatelll/ttyl"
  version "${version}"
  license "MIT"

  on_macos do
    on_arm do
$(archive darwin_arm64)
    end
    on_intel do
$(archive darwin_amd64)
    end
  end

  on_linux do
    on_arm do
$(archive linux_arm64)
    end
    on_intel do
$(archive linux_amd64)
    end
  end

  def install
    bin.install "ttyl"
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/ttyl version")
  end
end
RUBY
